<script setup lang="ts">import {computed} from 'vue';import type {FactorMetric} from '../types/domain';import {fixed} from '../utils/format';const props=defineProps<{rows:FactorMetric[]}>();const sorted=computed(()=>[...props.rows].sort((a,b)=>b.st-a.st)),low=computed(()=>Math.min(0,...props.rows.flatMap(r=>[r.s1,r.st]))),high=computed(()=>Math.max(1,...props.rows.flatMap(r=>[r.s1,r.st])));const X=(v:number)=>90+(v-low.value)/(high.value-low.value)*330;</script><template><div class="sobol-bars"><svg :viewBox="'0 0 450 '+(70+rows.length*39)" role="img" aria-label="Sobol一阶与Jansen总效应指数"><g v-for="tick in [low,(low+high)/2,high]" :key="tick"><line :x1="X(tick)" :x2="X(tick)" y1="28" :y2="40+rows.length*39" class="grid-line"/><text :x="X(tick)" y="17" text-anchor="middle">{{fixed(tick,2)}}</text></g><g v-for="(r,i) in sorted" :key="r.factor_id"><text x="4" :y="48+i*39">{{r.factor_id}}</text><line :x1="X(0)" :x2="X(r.st)" :y1="42+i*39" :y2="42+i*39" class="st-bar"/><line :x1="X(0)" :x2="X(r.s1)" :y1="51+i*39" :y2="51+i*39" class="s1-bar"/><text :x="X(r.st)+5" :y="43+i*39" class="bar-value">{{fixed(r.st,3)}}</text></g><text x="90" :y="63+rows.length*39">一阶 S1 / 赭色细线　总效应 ST / 砖红粗线</text></svg><p class="plot-note">按ST排序；负值或大于1的样本估计保留。点估计不附置信区间，不等于实际节能收益。</p></div></template>
